{
  "gate_token": "vHi9HZOOFyazyY-0rgyECg",
  "title": "The Glass Diver and the Ruined Crown",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined royal city.",
      "visual_description": "A windswept hill at dusk overlooking a shattered skyline of broken spires and tilted banners; ink-stained hands pin a map down with a brass compass.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of three temptations ahead.",
      "visual_description": "A small oil lamp held aloft, its single eye glowing in the flame, casting three flickering shadow-shapes on the map: a gate, a tower, and a bridge.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the cracked castle gates.",
      "visual_description": "A clockwork fox with blue glass eyes crouched in rubble before towering iron gates hung with torn royal banners; its key-wind tail glints in moonlight.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver arrives through a shattered shop window.",
      "visual_description": "A figure in a clear diving helmet steps out of a tall mirror set in a broken storefront, coat shimmering with reflected lantern fires.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The team gathers around a frightened huddle in an alley.",
      "visual_description": "A narrow alley of leaning houses; hooded figures cower in a doorway as the lamp's eye softens to a gentler glow.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Mara marks the route past the cursed tower.",
      "visual_description": "Close-up of a map being inked with a quick route line that loops wide around a black spiral tower drawn in the corner.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "An armored patrol marches the cobbled square.",
      "visual_description": "From a rooftop view, columns of plated figures with pikes cross a moonlit plaza; the clockwork fox watches from behind a chimney.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp whispers the patrol's pattern.",
      "visual_description": "The lamp held low behind a parapet, its flame eye narrowed; faint glowing lines trace the patrol's loop across the stones below.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "Glass Diver slips through a tall stained-glass window.",
      "visual_description": "A figure dives smoothly into a cathedral window as if into water; colored panes ripple around the helmet's seal.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Inside, a sleeping official slumps over a ledger.",
      "visual_description": "A dim records office; an official snores on a ledger book, stamped papers stuck to his sleeves, keys dangling from his belt.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "Tin Fox steals the ring of keys without a sound.",
      "visual_description": "The clockwork fox up on hind legs, delicately lifting a key ring with its teeth as the official's hand twitches in a dream.",
      "characters": ["tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door hums behind a tapestry.",
      "visual_description": "A heavy tapestry pulled aside to reveal a door of pulsing runes, blue light leaking between its planks.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The oracle lamp speaks the door's true name.",
      "visual_description": "The lamp lifted to the runes; its flame eye widens and the door's lines bend into a single bright keyhole.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "They find the captive in a small stone cell.",
      "visual_description": "A round cell with a single barred window; a wrapped figure rises as Mara enters, the diver standing watch with a mirror shard.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Distant roars rumble from the cursed tower.",
      "visual_description": "Through the cell window, the black tower lights up red and a long shadow uncoils across the clouds; the fox's ears prick.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Glass Diver opens an escape through a tall mirror.",
      "visual_description": "A cracked hallway mirror ripples like a pond; the diver holds it open as the others step toward it, lamp first.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across the long river bridge.",
      "visual_description": "A stone bridge over black water under a red sky; four figures run, the fox bounding ahead, banners snapping behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "Beyond the bridge, Mara folds the map and exhales.",
      "visual_description": "A quiet ridge at dawn; the city smoulders behind them as the cartographer closes her compass, lamp dimmed, fox curled at her boots.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    }
  ]
}

